arguments.new_str:
using Microsoft.Extensions.ML;
using ChurnPredictor.Models;
using ChurnPredictor.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<ChurnModelService>();
builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>();

var app = builder.Build();

// Train model on startup and configure the prediction engine pool
var modelService = app.Services.GetRequiredService<ChurnModelService>();
modelService.TrainModel();
var predictionPool = app.Services.GetRequiredService<PredictionEnginePool<ChurnInput, ChurnPrediction>>();
var mlContext = new Microsoft.ML.MLContext();
using var stream = File.OpenRead(modelService.ModelPath);
var model = mlContext.Model.Load(stream, out _);
predictionPool.GetPredictionEngine(string.Empty); // warm up

// Re-register pool with model from file
builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<ChurnModelService>();
builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>()
    .FromFile(modelPath: modelService.ModelPath, watchForChanges: false);

app = builder.Build();

// Train again since we rebuilt
app.Services.GetRequiredService<ChurnModelService>().TrainModel();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (PredictionEnginePool<ChurnInput, ChurnPrediction> pool, ChurnInput input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        prediction.PredictedLabel,
        prediction.Probability,
        prediction.Score
    });
});

app.Run();

